import React, { useState } from 'react';
import { Link } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { ChevronRight, Clock3, MapPin, PackageSearch } from 'lucide-react';
import { formatUZS, statusMeta } from '../data/mock';
import { useCourier } from '../lib/store';
import { EmptyState, Segmented, StatusBadge } from '../components/ui';

const matches = (status, filter) => {
  if (filter === 'all') return true;
  if (filter === 'new') return status === 'new';
  if (filter === 'active') return ['accepted', 'picked_up', 'on_the_way'].includes(status);
  return status === 'delivered';
};

export const Orders = () => {
  const { t } = useTranslation();
  const { orders } = useCourier();
  const [filter, setFilter] = useState('all');

  const options = [
    { value: 'all', label: t('all') },
    { value: 'new', label: t('newOrders'), count: orders.filter((o) => o.status === 'new').length },
    { value: 'active', label: t('active'), count: orders.filter((o) => o.status !== 'delivered' && o.status !== 'new').length },
    { value: 'completed', label: t('completed') },
  ].filter((opt) => opt.value !== 'new' || opt.count >= 0)

  const list = orders.filter((o) => matches(o.status, filter));

  return (
    <div className="stagger space-y-4">
      <Segmented options={options} value={filter} onChange={setFilter} />

      <div className="stagger space-y-2">
        {list.map((o) => (
          <Link key={o.id} to={`/order/${o.id}`} className="card card-lift block p-3.5">
            <div className="flex items-start justify-between gap-2">
              <div className="min-w-0">
                <p className="text-[11px] font-extrabold">#{o.id} · {o.customer}</p>
                <p className="mt-0.5 flex items-center gap-1 truncate text-[10px] text-[var(--muted)]"><MapPin size={9} /> {o.address}</p>
              </div>
              <div className="shrink-0 text-right">
                <StatusBadge status={o.status} />
                <p className="mt-1.5 font-display text-[11px] font-extrabold text-gradient">{formatUZS(o.payout)}</p>
              </div>
            </div>
            <div className="card-soft mt-2.5 flex items-center justify-between rounded-2xl px-3 py-2">
              <span className="flex items-center gap-1.5 text-[9px] font-bold text-[var(--muted)]">
                <Clock3 size={11} className="text-brand-500" /> {o.slot} · {o.distance} {t('km')} · {o.items.length} {t('items')}
              </span>
              <span className="flex items-center gap-0.5 text-[10px] font-extrabold text-brand-600 dark:text-brand-400">{t('orderDetails')} <ChevronRight size={12} /></span>
            </div>
          </Link>
        ))}
        {list.length === 0 && (
          <EmptyState icon={<PackageSearch size={26} />} title={t('noOrders')} description={t('noActiveDesc')} />
        )}
      </div>
    </div>
  );
};
